using System;
using System.IO;
using System.Text;
namespace HprGhost {
 public static class StartupInstallTests {
  public static void Run(Action<bool,string> check,string folder){
   string test=Path.Combine(folder,"start-"+Guid.NewGuid().ToString("N").Substring(0,8)),steam=Path.Combine(test,"Steam"),lib=Path.Combine(test,"游戏库"),apps=Path.Combine(lib,"steamapps"),game=Path.Combine(apps,"common","Hot Pursuit 测试"),prefs=Path.Combine(test,"PlaybackDisabled.txt");Directory.CreateDirectory(Path.Combine(steam,"steamapps"));Directory.CreateDirectory(Path.Combine(game,"VEHICLES"));File.WriteAllBytes(Path.Combine(game,"NFS11Remastered.exe"),new byte[]{0});File.WriteAllBytes(Path.Combine(game,"SHADERS.BNDL"),new byte[]{0});File.WriteAllText(Path.Combine(steam,"steamapps","libraryfolders.vdf"),"\"libraryfolders\" { \"1\" { \"path\" \""+lib.Replace("\\","\\\\")+"\" } }");string manifest=Path.Combine(apps,"appmanifest_1328660.acf");File.WriteAllText(manifest,"\"AppState\" { \"appid\" \"1328660\" \"installdir\" \"Hot Pursuit 测试\" }");
   Func<string> channel=delegate{return "Local\\HPRGhostStartupTest_"+Guid.NewGuid().ToString("N");};bool running=false;
   try{
    check(SteamGameDiscovery.Find(new[]{steam})==Path.GetFullPath(game),"startup discovers a non-default Unicode Steam library from the actual game manifest without a running game or saved path");File.WriteAllText(manifest,"\"appid\" \"42\" \"installdir\" \"Hot Pursuit 测试\"");check(SteamGameDiscovery.Find(new[]{steam})=="","Steam discovery ignores an unrelated application's manifest");File.WriteAllText(manifest,"\"appid\" \"1328660\" \"installdir\" \"..\\..\\outside\"");check(SteamGameDiscovery.Find(new[]{steam})=="","Steam discovery rejects an install-directory traversal");
    using(var bridge=new NativePlayback(null,channel(),true,delegate{return running;},prefs)){bridge.SetGameRoot(game);check(File.Exists(Path.Combine(game,NativeComponent.FileName))&&AsiLoader.OwnsLoader(game)&&bridge.SetupStatus=="回放组件已就绪。"&&!bridge.Ready&&bridge.CompletedInstalls==1,"startup installs both components before any replay is selected and reports ready to launch the game");bridge.SetGameRoot(game);bridge.ResumeInstallation();check(bridge.CompletedInstalls==1,"matching installed components do not trigger repeated installation-complete alerts");}
    AsiLoader.Uninstall(game,true,false);running=true;using(var bridge=new NativePlayback(null,channel(),true,delegate{return running;},prefs)){bridge.SetGameRoot(game);check(File.Exists(Path.Combine(game,NativeComponent.FileName))&&AsiLoader.OwnsLoader(game)&&bridge.SetupStatus=="回放组件已安装，请重启游戏后使用。"&&bridge.CompletedInstalls==1&&bridge.RestartRequired,"when a game is already open, startup installs missing files immediately and explicitly requests a restart");running=false;bridge.Update(false,45,0);check(bridge.SetupStatus=="回放组件已就绪。","the startup restart reminder clears after the game exits");bridge.Unload();AsiLoader.Uninstall(game,true,false);}
    using(var bridge=new NativePlayback(null,channel(),true,delegate{return running;},prefs)){bridge.SetGameRoot(game);bridge.Update(false,45,0);check(!File.Exists(Path.Combine(game,NativeComponent.FileName))&&!File.Exists(Path.Combine(game,AsiLoader.FileName))&&File.Exists(prefs),"uninstall persists across application restarts and prevents startup from reinstalling components");bridge.ResumeInstallation();check(File.Exists(Path.Combine(game,NativeComponent.FileName))&&AsiLoader.OwnsLoader(game)&&!File.Exists(prefs)&&bridge.CompletedInstalls==1,"explicitly loading playback re-enables installation after an uninstall");}
    File.WriteAllText(Path.Combine(game,NativeComponent.FileName),"Older HPRGHOST_NATIVE_COMPONENT_V3 build");running=true;using(var bridge=new NativePlayback(null,channel(),true,delegate{return running;},prefs)){bridge.SetGameRoot(game);check(File.ReadAllText(Path.Combine(game,NativeComponent.FileName)).StartsWith("Older")&&bridge.SetupStatus=="请退出游戏，等待组件更新后重新启动游戏。","an existing native component is preserved while the game is running and the update is clearly pending");running=false;System.Threading.Thread.Sleep(1100);bridge.Update(false,45,0);check(AsiLoader.Hash(File.ReadAllBytes(Path.Combine(game,NativeComponent.FileName)))==NativeComponent.Digest&&bridge.SetupStatus=="回放组件已就绪。","a pending native update completes after game exit without selecting any replay");}
   }finally{if(!Path.GetFullPath(test).StartsWith(Path.GetFullPath(folder)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("Unsafe startup test cleanup");Directory.Delete(test,true);}
  }
 }
}



